"""
build_gallery.py - Portable Thumbdrive Gallery Builder
Scans photos and videos on the thumbdrive, extracts EXIF/IPTC/XMP metadata (people face regions, tags, dates),
generates optimized thumbnails and face avatars, and produces a zero-CORS gallery_data.js.
Designed to sit in the /Gallery folder and index root media directories.
"""

import os
import shutil
import zlib
import base64
import sys
import time
import json
import hashlib
import datetime
import re
import warnings
import subprocess
from pathlib import Path

try:
    from PIL import Image, ExifTags, ImageOps
    Image.MAX_IMAGE_PIXELS = None  # Allow high-res panoramas & flatbed scans without DecompressionBombWarning
    HAS_PILLOW = True
except ImportError:
    Image = ExifTags = ImageOps = None
    HAS_PILLOW = False

# Ensure UTF-8 output encoding across Windows consoles & redirect pipes
if sys.platform.startswith("win"):
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
        sys.stderr.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

# ANSI Terminal Colors
if sys.platform.startswith("win"):
    try:
        os.system("")  # Enables ANSI escape sequences in Windows console
    except Exception:
        pass

CLR_RESET = "\033[0m"
CLR_BOLD = "\033[1m"
CLR_CYAN = "\033[96m"
CLR_GREEN = "\033[92m"
CLR_YELLOW = "\033[93m"
CLR_BLUE = "\033[94m"
CLR_GRAY = "\033[90m"

# Suppress benign Pillow TIFF/EXIF warnings on photos with malformed maker notes
warnings.filterwarnings("ignore", category=UserWarning, module="PIL")
warnings.filterwarnings("ignore", message=".*Tag data larger than file.*")

